text:
Emprego formal em números
Indicador mensal do mercado de trabalho formal, calculado a partir dos microdados do Novo Cadastro Geral de Empregados e Desempregados (Novo CAGED) com o pacote datacaged e atualizado automaticamente a cada nova divulgação.


dados = FileAttachment("dados/caged_saldo.csv").csv({typed: true})
  .then(ds =&gt; ds.map(d =&gt; ({...d, data: new Date(d.competencia)})))

viewof recorte = Inputs.radio(
  ["Brasil", "Rio Grande do Norte", "Mossoró"],
  {value: "Rio Grande do Norte"}
)

viewof janela = Inputs.radio(
  new Map([["Últimos 24 meses", 24], ["Desde 2020", 1000]]),
  {value: 24}
)























serie = dados
  .filter(d =&gt; d.recorte === recorte)
  .sort((a, b) =&gt; a.data - b.data)

recorteJanela = serie.slice(-janela)
ultimo = serie[serie.length - 1]
anoUltimo = ultimo.data.getUTCFullYear()
acumAno = d3.sum(serie.filter(d =&gt; d.data.getUTCFullYear() === anoUltimo), d =&gt; d.saldo)
acum12 = d3.sum(serie.slice(-12), d =&gt; d.saldo)

fmt = v =&gt; (v &gt; 0 ? "+" : "") + v.toLocaleString("pt-BR")
mesAno = d =&gt; d.toLocaleDateString("pt-BR", {month: "long", year: "numeric", timeZone: "UTC"})
mesCurto = d =&gt; d.toLocaleDateString("pt-BR", {month: "short", year: "2-digit", timeZone: "UTC"}).replace(". de ", "/").replace(" de ", "/")

html`&lt;div class="kpis"&gt;
  &lt;div class="kpi"&gt;&lt;div class="kpi-rotulo"&gt;Saldo do mês&lt;/div&gt;
    &lt;div class="kpi-valor"&gt;${fmt(ultimo.saldo)}&lt;/div&gt;
    &lt;div class="kpi-nota"&gt;${mesAno(ultimo.data)}&lt;/div&gt;&lt;/div&gt;
  &lt;div class="kpi"&gt;&lt;div class="kpi-rotulo"&gt;Acumulado no ano&lt;/div&gt;
    &lt;div class="kpi-valor"&gt;${fmt(acumAno)}&lt;/div&gt;
    &lt;div class="kpi-nota"&gt;janeiro a ${ultimo.data.toLocaleDateString("pt-BR", {month: "long", timeZone: "UTC"})} de ${anoUltimo}&lt;/div&gt;&lt;/div&gt;
  &lt;div class="kpi"&gt;&lt;div class="kpi-rotulo"&gt;Últimos 12 meses&lt;/div&gt;
    &lt;div class="kpi-valor"&gt;${fmt(acum12)}&lt;/div&gt;
    &lt;div class="kpi-nota"&gt;soma dos saldos mensais&lt;/div&gt;&lt;/div&gt;
  &lt;div class="kpi"&gt;&lt;div class="kpi-rotulo"&gt;Admissões no mês&lt;/div&gt;
    &lt;div class="kpi-valor"&gt;${ultimo.admissoes.toLocaleString("pt-BR")}&lt;/div&gt;
    &lt;div class="kpi-nota"&gt;${ultimo.desligamentos.toLocaleString("pt-BR")} desligamentos&lt;/div&gt;&lt;/div&gt;
&lt;/div&gt;`








































































Plot.plot({
  height: 260,
  marginLeft: 64,
  style: {fontFamily: "IBM Plex Mono, monospace", fontSize: "11px", background: "transparent"},
  x: {type: "band", label: null, tickFormat: d =&gt; mesCurto(new Date(d)),
      ticks: recorteJanela.filter((d, i) =&gt; i % (janela &gt; 24 ? 6 : 3) === 0).map(d =&gt; d.data.getTime())},
  y: {label: "Saldo (admissões menos desligamentos)", grid: true,
      tickFormat: v =&gt; v.toLocaleString("pt-BR")},
  color: {domain: [true, false], range: ["#1f8fae", "#d97706"]},
  marks: [
    Plot.ruleY([0], {stroke: "#94a3b8"}),
    Plot.barY(recorteJanela, {
      x: d =&gt; d.data.getTime(), y: "saldo", fill: d =&gt; d.saldo &gt;= 0,
      inset: 0.5,
      title: d =&gt; `${mesAno(d.data)}\nSaldo: ${fmt(d.saldo)}\nAdmissões: ${d.admissoes.toLocaleString("pt-BR")}\nDesligamentos: ${d.desligamentos.toLocaleString("pt-BR")}`,
      tip: true
    })
  ]
})







Fonte: Ministério do Trabalho e Emprego, Novo CAGED (movimentações declaradas no prazo, sem ajustes). Elaboração própria com o pacote datacaged. Valores mensais por competência.

Mercado de trabalho contábil
Admissões, desligamentos e salário de admissão das ocupações contábeis no emprego formal, segundo a Classificação Brasileira de Ocupações (CBO): Contador (2522-10), Auditor (2522-05), Perito contábil (2522-15), Técnico de contabilidade (3511-05) e Auxiliar de contabilidade (4131-10).


contabil = FileAttachment("dados/caged_contabil.csv").csv({typed: true})
  .then(ds =&gt; ds.map(d =&gt; ({...d, data: new Date(d.competencia), ano: new Date(d.competencia).getUTCFullYear()})))

ocupacoesTodas = ["Contador", "Auditor", "Perito contábil", "Técnico de contabilidade", "Auxiliar de contabilidade"]

viewof recorteCont = Inputs.radio(
  ["Brasil", "Nordeste", "Rio Grande do Norte"],
  {value: "Rio Grande do Norte"}
)

viewof ocupSel = Inputs.checkbox(ocupacoesTodas, {value: ocupacoesTodas})






























contR = contabil.filter(d =&gt; d.recorte === recorteCont && ocupSel.includes(d.ocupacao))
compsCont = [...new Set(contabil.map(d =&gt; d.data.getTime()))].sort((a, b) =&gt; a - b)
ult12 = new Set(compsCont.slice(-12))
ultimaCont = new Date(compsCont[compsCont.length - 1])
inicio12 = new Date(compsCont[compsCont.length - 12])
c12 = contR.filter(d =&gt; ult12.has(d.data.getTime()))
somaC = (arr, k) =&gt; d3.sum(arr, d =&gt; d[k])
salMedio = arr =&gt; somaC(arr, "salario_soma") / Math.max(1, somaC(arr, "salario_n"))
brl = v =&gt; v.toLocaleString("pt-BR", {style: "currency", currency: "BRL", maximumFractionDigits: 0})
periodo12 = `${mesCurto(inicio12)} a ${mesCurto(ultimaCont)}`

html`&lt;div class="kpis"&gt;
  &lt;div class="kpi"&gt;&lt;div class="kpi-rotulo"&gt;Admissões (12 meses)&lt;/div&gt;
    &lt;div class="kpi-valor"&gt;${somaC(c12, "admissoes").toLocaleString("pt-BR")}&lt;/div&gt;
    &lt;div class="kpi-nota"&gt;${periodo12}&lt;/div&gt;&lt;/div&gt;
  &lt;div class="kpi"&gt;&lt;div class="kpi-rotulo"&gt;Saldo (12 meses)&lt;/div&gt;
    &lt;div class="kpi-valor"&gt;${fmt(somaC(c12, "admissoes") - somaC(c12, "desligamentos"))}&lt;/div&gt;
    &lt;div class="kpi-nota"&gt;admissões menos desligamentos&lt;/div&gt;&lt;/div&gt;
  &lt;div class="kpi"&gt;&lt;div class="kpi-rotulo"&gt;Salário médio de admissão&lt;/div&gt;
    &lt;div class="kpi-valor"&gt;${brl(salMedio(c12))}&lt;/div&gt;
    &lt;div class="kpi-nota"&gt;últimos 12 meses, valor nominal&lt;/div&gt;&lt;/div&gt;
&lt;/div&gt;`















































































tabela12 = ocupSel.map(o =&gt; {
  const r = c12.filter(d =&gt; d.ocupacao === o)
  return {o, adm: somaC(r, "admissoes"), desl: somaC(r, "desligamentos"), sal: salMedio(r), n: somaC(r, "salario_n")}
})

html`&lt;table class="table table-sm tabela-contabil"&gt;
  &lt;thead&gt;&lt;tr&gt;&lt;th&gt;Ocupação&lt;/th&gt;&lt;th&gt;Admissões&lt;/th&gt;&lt;th&gt;Desligamentos&lt;/th&gt;&lt;th&gt;Saldo&lt;/th&gt;&lt;th&gt;Salário médio de admissão&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
  &lt;tbody&gt;${tabela12.map(r =&gt; html`&lt;tr&gt;
    &lt;td&gt;${r.o}&lt;/td&gt;
    &lt;td&gt;${r.adm.toLocaleString("pt-BR")}&lt;/td&gt;
    &lt;td&gt;${r.desl.toLocaleString("pt-BR")}&lt;/td&gt;
    &lt;td class="${r.adm - r.desl &lt; 0 ? "neg" : ""}"&gt;${fmt(r.adm - r.desl)}&lt;/td&gt;
    &lt;td&gt;${r.n &gt;= 10 ? brl(r.sal) : "—"}&lt;/td&gt;&lt;/tr&gt;`)}&lt;/tbody&gt;
&lt;/table&gt;`
















salAnual = d3.flatRollup(contR, v =&gt; ({sal: salMedio(v), n: somaC(v, "salario_n")}), d =&gt; d.ano, d =&gt; d.ocupacao)
  .map(([ano, ocupacao, v]) =&gt; ({ano, ocupacao, ...v, sal: v.n &gt;= 10 ? v.sal : NaN}))
  .sort((a, b) =&gt; a.ano - b.ano)

Plot.plot({
  height: 280,
  marginLeft: 70,
  style: {fontFamily: "IBM Plex Mono, monospace", fontSize: "11px", background: "transparent"},
  x: {label: null, tickFormat: d =&gt; String(d), ticks: [...new Set(salAnual.map(d =&gt; d.ano))]},
  y: {label: "Salário médio de admissão (R$, nominal)", grid: true, tickFormat: v =&gt; v.toLocaleString("pt-BR")},
  color: {domain: ocupacoesTodas, range: ["#0e7490", "#7c3aed", "#d97706", "#64748b", "#94a3b8"], legend: true},
  marks: [
    Plot.line(salAnual, {x: "ano", y: "sal", stroke: "ocupacao", strokeWidth: 2}),
    Plot.dot(salAnual.filter(d =&gt; d.n &gt;= 10), {x: "ano", y: "sal", fill: "ocupacao", r: 3,
      title: d =&gt; `${d.ocupacao}, ${d.ano}\n${brl(d.sal)} (${d.n.toLocaleString("pt-BR")} admissões)`, tip: true})
  ]
})
















Fonte: Ministério do Trabalho e Emprego, Novo CAGED (movimentações declaradas no prazo). Elaboração própria com o pacote datacaged. O salário médio de admissão considera apenas admissões não intermitentes com salário contratual entre R$ 500 e R$ 60.000, em valores nominais; médias com menos de 10 admissões não são exibidas. O ano corrente reúne apenas os meses já divulgados.
